import type { Metadata } from "next"
import { GeistSans } from "geist/font/sans"
import type { ReactNode } from "react"

import { ThemeProvider } from "../components/theme-provider"

import "./globals.css"

export const metadata: Metadata = {
  title: "Jon Doe",
  description:
    "Fullstack developer — a scroll-scrubbed timeline of sites shipped and teams joined.",
}

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html
      lang="en"
      className={`h-full ${GeistSans.variable} antialiased`}
      suppressHydrationWarning
    >
      <body
        className={`${GeistSans.className} flex min-h-svh flex-col bg-background font-sans text-foreground`}
      >
        <ThemeProvider>{children}</ThemeProvider>
      </body>
    </html>
  )
}

import { ClaireCompanyIcons } from "../components/company-icons"
import { Avatar } from "../components/avatar"
import { Lifeline, LifelineLegend } from "../components/lifeline"
import {
  LifelineFooter,
  LifelineNav,
  LifelineShell,
  LifelineStage,
} from "../components/lifeline-shell"
import { ThemeSwitcher } from "../components/theme-switcher"
import { getJonDoeLifeline } from "../lib/media"

export default function HomePage() {
  const life = getJonDoeLifeline()

  return (
    <LifelineShell className="lifeline-typeset">
      <LifelineNav
        logo={
          <span className="flex items-center gap-3">
            <Avatar />
            <span className="text-sm font-semibold tracking-tight text-foreground">
              {life.name}
            </span>
          </span>
        }
        logoLabel={life.name}
      >
        <ThemeSwitcher />
      </LifelineNav>

      <ClaireCompanyIcons />

      <LifelineStage>
        <Lifeline
          markers={life.markers}
          birthYear={life.birthYear}
          title={life.name}
          className="h-full"
        />
      </LifelineStage>

      <LifelineFooter containerClassName="justify-center">
        <LifelineLegend items={life.legend} />
      </LifelineFooter>
    </LifelineShell>
  )
}

import Image from "next/image"

import { resolveAvatarSrc } from "../lib/media"

export function Avatar({ className = "size-10" }: { className?: string }) {
  const src = resolveAvatarSrc()

  return (
    <Image
      src={src}
      alt=""
      width={40}
      height={40}
      unoptimized
      priority
      loading="eager"
      className={`shrink-0 rounded-full object-cover ${className}`}
    />
  )
}

import type { ReactNode } from "react"
import { cn } from "@/lib/utils"

const CONTAINER = "mx-auto flex w-full max-w-5xl items-center px-6"

export function LifelineShell({
  children,
  className,
}: {
  children: ReactNode
  className?: string
}) {
  return (
    <div
      className={cn("flex h-dvh flex-col overflow-hidden bg-background text-foreground antialiased transition-colors duration-300",
        className,
      )}
    >
      {children}
    </div>
  )
}

export function LifelineNav({
  logo,
  logoHref = "/",
  logoLabel = "Home",
  children,
  className,
  containerClassName,
}: {
  logo: ReactNode
  logoHref?: string
  logoLabel?: string
  children?: ReactNode
  className?: string
  containerClassName?: string
}) {
  return (
    <nav
      className={cn("fixed inset-x-0 top-0 z-50 border-b border-border bg-background/80 backdrop-blur-xl transition-colors duration-300",
        className,
      )}
    >
      <div
        data-site-nav-inner
        className={cn(CONTAINER, "h-16 justify-between", containerClassName)}
      >
        <a
          href={logoHref}
          data-site-nav-logo
          aria-label={logoLabel}
          className="text-foreground transition-[color,opacity] duration-300 hover:opacity-70"
        >
          {logo}
        </a>

        {children ? (
          <div className="flex items-center gap-8">{children}</div>
        ) : null}
      </div>
    </nav>
  )
}

export function LifelineStage({
  children,
  className,
}: {
  children: ReactNode
  className?: string
}) {
  return (
    <main
      className={cn("flex-1 min-h-0 overflow-y-auto pt-16 md:overflow-hidden",
        className,
      )}
    >
      {children}
    </main>
  )
}

export function LifelineFooter({
  children,
  className,
  containerClassName,
}: {
  children?: ReactNode
  className?: string
  containerClassName?: string
}) {
  return (
    <footer
      className={cn("shrink-0 border-t border-border bg-background/95 backdrop-blur-sm transition-colors duration-300",
        className,
      )}
    >
      <div
        className={cn(
          CONTAINER,
          "h-16 justify-between gap-6",
          containerClassName,
        )}
      >
        {children}
      </div>
    </footer>
  )
}

"use client"

import { useLayoutEffect, useState } from "react"
import { cn } from "@/lib/utils"

import { LifelineDesktop } from "./lifeline-desktop"
import { LifelineVertical } from "./lifeline-vertical"
import { LIFELINE_MOBILE_BREAKPOINT } from "./lifeline-layout"
import type { LifelineProps } from "./types"
import "./lifeline.css"

export function Lifeline(props: LifelineProps) {
  const [isMobile, setIsMobile] = useState<boolean | null>(null)

  useLayoutEffect(() => {
    const query = window.matchMedia(
      `(min-width: ${LIFELINE_MOBILE_BREAKPOINT}px)`,
    )
    const update = () => setIsMobile(!query.matches)

    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])

  if (isMobile === null) {
    return <div className="invisible h-full" aria-hidden="true" />
  }

  if (isMobile) {
    return (
      <div
        className={
          props.mode === "embed"
            ? cn(
                "lifeline-typeset h-full overflow-y-auto pt-5",
                props.className,
              )
            : "lifeline-typeset pt-5"
        }
      >
        <LifelineVertical {...props} />
      </div>
    )
  }

  return (
    <LifelineDesktop
      {...props}
      className={cn("lifeline-typeset pt-5", props.className)}
    />
  )
}

import type { ComponentType } from "react"
import { cn } from "@/lib/utils"

export type CompanyIconId = string

export interface CompanyIconEntry {
  icon: ComponentType<{ className?: string }>
  darkIcon?: ComponentType<{ className?: string }>
  sizeClassName?: string
}

const registry: Record<string, CompanyIconEntry> = {}

export function registerCompanyIcons(
  entries: Record<string, CompanyIconEntry>,
) {
  Object.assign(registry, entries)
}

export function CompanyIcon({
  id,
  label,
  className,
}: {
  id: CompanyIconId
  label: string
  className?: string
}) {
  const entry = registry[id]

  if (entry) {
    const Icon = entry.icon
    const DarkIcon = entry.darkIcon
    return (
      <span
        className={cn("inline-flex shrink-0 items-center justify-center text-foreground transition-colors duration-300",
          entry.sizeClassName ?? "h-4 w-4",
          className,
        )}
        aria-label={label}
        title={label}
      >
        {DarkIcon ? (
          <>
            <Icon className="h-full w-full dark:hidden" aria-hidden="true" />
            <DarkIcon
              className="hidden h-full w-full dark:block"
              aria-hidden="true"
            />
          </>
        ) : (
          <Icon className="h-full w-full" aria-hidden="true" />
        )}
      </span>
    )
  }

  return (
    <span
      title={label}
      aria-label={label}
      className={cn("inline-flex h-5 w-5 select-none items-center justify-center rounded-full text-[10px] font-semibold uppercase leading-none ring-1 ring-current/30",
        className,
      )}
    >
      {label.charAt(0)}
    </span>
  )
}

"use client"

import { useMemo, type CSSProperties } from "react"
import { cn } from "@/lib/utils"
import {
  LifelineStickyLabels,
  LIFELINE_STICKY_SHIELD_WIDTH,
} from "./lifeline-labels"
import { LifelineMarkerColumn } from "./lifeline-marker"
import type { LifelineEventImage, LifelineProps } from "./types"
import { getLifelineEventImage } from "./lifeline-event"
import { LifelineHoverImageProvider } from "./lifeline-hover-image"
import { useLifelineIntro } from "./use-lifeline-intro"
import { useLifelineScroll } from "./use-lifeline-scroll"
import { getMarkerWidth } from "./lifeline-utils"

export function LifelineDesktop({
  markers,
  birthYear,
  className,
  title = "Lifeline",
  mode = "auto",
}: LifelineProps) {
  const widths = useMemo(
    () =>
      markers.map((marker, index) =>
        getMarkerWidth(marker, markers[index + 1]?.year),
      ),
    [markers],
  )

  const hoverImages = useMemo(() => {
    const images: LifelineEventImage[] = []
    for (const marker of markers) {
      for (const event of marker.events) {
        const image = getLifelineEventImage(event)
        if (image) images.push(image)
      }
    }
    return images
  }, [markers])

  const intro = useLifelineIntro(widths)
  const isIntroAnimating = intro.shouldPlay && intro.isPlaying

  const {
    sectionRef,
    trackRef,
    labelsRef,
    setMarkerRef,
    isLayoutReady,
    isEmbed,
    introArmed,
  } = useLifelineScroll(markers.length, {
    mode,
    introLocked: isIntroAnimating,
    introAnimating: isIntroAnimating,
    introSkipped: !intro.shouldPlay,
    introRailMs: intro.railDuration,
    introGetTrackProgress: intro.getTrackProgressAtTime,
    onIntroScrollStart: intro.startIntroTimer,
    onIntroSettleComplete: intro.completeIntro,
  })

  const introWaitingInView = isEmbed && intro.shouldPlay && !introArmed
  const showIntro = isIntroAnimating && isLayoutReady && !introWaitingInView

  const trackWidth =
    LIFELINE_STICKY_SHIELD_WIDTH + widths.reduce((sum, width) => sum + width, 0)

  const introStyle = {
    "--lifeline-labels-ms": `${intro.labelsDuration}ms`,
    "--lifeline-rail-ms": `${intro.railDuration}ms`,
  } as CSSProperties

  return (
    <section
      ref={sectionRef}
      data-lifeline-mode={isEmbed ? "embed" : "page"}
      tabIndex={isEmbed ? 0 : undefined}
      className={cn("relative h-full min-h-0 select-none overflow-hidden [&_a]:cursor-pointer",
        isEmbed &&
          "touch-pan-y focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        (!isLayoutReady || introWaitingInView) && "invisible",
        className,
      )}
      aria-label={title}
      style={showIntro ? introStyle : undefined}
    >
      <LifelineHoverImageProvider preload={hoverImages}>
      <div
        className="flex h-full items-center overflow-hidden"
        style={{ alignItems: "safe center" }}
      >
        <div
          ref={trackRef}
          className="relative flex w-max items-start will-change-transform [--lifeline-global-events-top:calc(14.5rem+40px)] [--lifeline-rail:5rem]"
          style={{ width: trackWidth }}
        >
          <div
            ref={labelsRef}
            className="lifeline-labels shrink-0 bg-background transition-colors duration-300 will-change-transform"
            style={{ width: LIFELINE_STICKY_SHIELD_WIDTH }}
          >
            <div className={cn(showIntro && "lifeline-labels-intro")}>
              <LifelineStickyLabels />
            </div>
          </div>

          <div className="relative">
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-0 top-[var(--lifeline-rail)] h-px overflow-hidden"
            >
              <div
                className={cn("h-px w-full border-t border-dashed border-border transition-colors duration-300",
                  showIntro && "lifeline-rail-intro",
                )}
              />
            </div>

            <div className="relative flex items-start">
              {markers.map((marker, index) => (
                <LifelineMarkerColumn
                  key={marker.id}
                  ref={(node) => setMarkerRef(index, node)}
                  marker={marker}
                  birthYear={birthYear}
                  minWidth={widths[index]}
                  animateIntro={showIntro}
                  introDelay={intro.getMarkerDelay(index)}
                  introDuration={intro.getMarkerFadeDuration(index)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      </LifelineHoverImageProvider>
    </section>
  )
}

import type {
  LifelineEvent,
  LifelineEventCategory,
  LifelineEventClip,
  LifelineEventImage,
  LifelineEventSegment,
} from "./types"

export const LIFELINE_EVENT_CATEGORY_DOT_CLASS: Record<
  LifelineEventCategory,
  string
> = {
  work: "bg-amber-500",
  college: "bg-violet-500",
  destination: "bg-teal-500",
}

function getEventContent(
  event: LifelineEvent,
): string | LifelineEventSegment[] {
  if (typeof event === "object" && !Array.isArray(event) && "text" in event) {
    return event.text
  }

  return event
}

export function getLifelineEventImage(
  event: LifelineEvent,
): LifelineEventImage | undefined {
  if (typeof event === "object" && !Array.isArray(event) && "image" in event) {
    return event.image
  }

  return undefined
}

export function getLifelineEventVideo(
  event: LifelineEvent,
): LifelineEventClip | undefined {
  if (typeof event === "object" && !Array.isArray(event) && "video" in event) {
    return event.video
  }

  return undefined
}

export function getLifelineEventCategory(
  event: LifelineEvent,
): LifelineEventCategory | undefined {
  if (
    typeof event === "object" &&
    !Array.isArray(event) &&
    "category" in event
  ) {
    return event.category
  }

  return undefined
}

export function LifelineEventText({
  event,
  className,
}: {
  event: LifelineEvent
  className?: string
}) {
  const content = getEventContent(event)

  if (typeof content === "string") {
    return <span className={className}>{content}</span>
  }

  return (
    <span className={className}>
      {content.map((segment, index) =>
        segment.type === "link" ? (
          <a
            key={index}
            href={segment.href}
            target="_blank"
            rel="noopener noreferrer"
            className="underline decoration-muted-foreground underline-offset-2 transition-colors duration-300 group-hover:text-foreground group-hover:decoration-foreground"
          >
            {segment.value}
          </a>
        ) : (
          <span key={index}>{segment.value}</span>
        ),
      )}
    </span>
  )
}

export function LifelineEventMedia({
  media,
  className,
}: {
  media: LifelineEventImage
  className?: string
}) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={media.src} alt={media.alt} loading="lazy" className={className} />
  )
}

export function getLifelineEventKey(event: LifelineEvent, index: number) {
  const content = getEventContent(event)

  if (typeof content === "string") return `${index}-${content}`

  return `${index}-${content.map((segment) => segment.value).join("")}`
}

"use client"

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  type ReactNode,
} from "react"
import { clamp, snapToDevicePixel } from "./lifeline-utils"
import type { LifelineEventImage } from "./types"

const FOLLOW_EASE = 0.16
const TILT_FACTOR = 0.14
const TILT_MAX_DEG = 7
const TILT_EASE = 0.1
const CURSOR_OFFSET_X = 24
const CURSOR_OFFSET_Y = 96

interface LifelineHoverImageApi {
  show: (image: LifelineEventImage) => void
  hide: () => void
}

interface LifelineHoverImageProviderProps {
  children: ReactNode
  preload?: LifelineEventImage[]
}

const LifelineHoverImageContext = createContext<LifelineHoverImageApi | null>(
  null,
)

export function useLifelineHoverImage() {
  return useContext(LifelineHoverImageContext)
}

export function LifelineHoverImageProvider({
  children,
  preload,
}: LifelineHoverImageProviderProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)
  const state = useRef({
    x: 0,
    y: 0,
    targetX: 0,
    targetY: 0,
    tilt: 0,
    visible: false,
    hoverCapable: false,
    frame: 0,
  })

  useEffect(() => {
    state.current.hoverCapable = window.matchMedia(
      "(hover: hover) and (pointer: fine)",
    ).matches

    const onMouseMove = (event: MouseEvent) => {
      state.current.targetX = event.clientX
      state.current.targetY = event.clientY
    }

    window.addEventListener("mousemove", onMouseMove, { passive: true })
    return () => {
      window.removeEventListener("mousemove", onMouseMove)
      cancelAnimationFrame(state.current.frame)
    }
  }, [])

  useEffect(() => {
    if (!preload?.length || !state.current.hoverCapable) return

    const warm = () => {
      preload.forEach(({ src }) => {
        if (!src) return
        const image = new window.Image()
        image.src = src
      })
    }

    if (typeof window.requestIdleCallback === "function") {
      const handle = window.requestIdleCallback(warm)
      return () => window.cancelIdleCallback(handle)
    }

    const timeout = window.setTimeout(warm, 2000)
    return () => window.clearTimeout(timeout)
  }, [preload])

  const stepRef = useRef<() => void>(() => {})

  const step = useCallback(() => {
    const s = state.current
    const container = containerRef.current
    if (!container) return

    const dx = s.targetX - s.x
    s.x += dx * FOLLOW_EASE
    s.y += (s.targetY - s.y) * FOLLOW_EASE

    const targetTilt = clamp(dx * TILT_FACTOR, -TILT_MAX_DEG, TILT_MAX_DEG)
    s.tilt += (targetTilt - s.tilt) * TILT_EASE

    if (
      Math.abs(s.targetX - s.x) < 0.1 &&
      Math.abs(s.targetY - s.y) < 0.1 &&
      Math.abs(s.tilt) < 0.05
    ) {
      s.x = s.targetX
      s.y = s.targetY
      s.tilt = 0
    }

    const rotate = s.tilt === 0 ? "" : ` rotate(${s.tilt}deg)`
    container.style.transform = `translate3d(${snapToDevicePixel(
      s.x + CURSOR_OFFSET_X,
    )}px, ${snapToDevicePixel(s.y - CURSOR_OFFSET_Y)}px, 0)${rotate}`

    if (s.visible) {
      s.frame = requestAnimationFrame(() => stepRef.current())
    }
  }, [])

  useEffect(() => {
    stepRef.current = step
  }, [step])

  const api = useMemo<LifelineHoverImageApi>(
    () => ({
      show(image) {
        const s = state.current
        const container = containerRef.current
        const img = imageRef.current
        if (!s.hoverCapable || !container || !img) return

        const targetSrc = new URL(image.src, window.location.origin).href

        if (img.src !== targetSrc) {
          img.style.visibility = "hidden"
          img.src = targetSrc
          img.alt = image.alt

          const reveal = () => {
            if (img.src === targetSrc) {
              img.style.visibility = "visible"
            }
          }

          if (img.complete) {
            reveal()
          } else {
            img.decode().then(reveal, reveal)
          }
        } else {
          img.style.visibility = "visible"
        }

        if (!s.visible) {
          s.x = s.targetX
          s.y = s.targetY
          s.tilt = 0
        }

        s.visible = true
        container.style.opacity = "1"
        img.style.transform = "scale(1)"

        cancelAnimationFrame(s.frame)
        s.frame = requestAnimationFrame(step)
      },
      hide() {
        const s = state.current
        const container = containerRef.current
        const img = imageRef.current
        if (!container || !img) return

        s.visible = false
        container.style.opacity = "0"
        img.style.transform = "scale(0.94)"
      },
    }),
    [step],
  )

  return (
    <LifelineHoverImageContext.Provider value={api}>
      {children}
      <div
        ref={containerRef}
        aria-hidden="true"
        className="pointer-events-none fixed left-0 top-0 z-[60] opacity-0 transition-opacity duration-200 ease-out will-change-transform"
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          ref={imageRef}
          alt=""
          className="w-[280px] scale-95 rounded-xl shadow-2xl ring-1 ring-black/10 transition-[transform,box-shadow] duration-200 ease-out dark:ring-white/15"
          decoding="async"
        />
      </div>
    </LifelineHoverImageContext.Provider>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { Play } from "lucide-react"
import { cn } from "@/lib/utils"
import {
  LifelineLightbox,
  type LifelineLightboxStart,
} from "./lifeline-lightbox"
import type { LifelineEventClip } from "./types"

export function LifelineInlineClip({
  clip,
  className,
}: {
  clip: LifelineEventClip
  className?: string
}) {
  const cardRef = useRef<HTMLDivElement>(null)
  const videoRef = useRef<HTMLVideoElement>(null)
  const [lightboxStart, setLightboxStart] =
    useState<LifelineLightboxStart | null>(null)

  useEffect(() => {
    const root = cardRef.current
    const video = videoRef.current
    if (!root || !video) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) video.preload = "auto"
      },
      { rootMargin: "80px" },
    )
    observer.observe(root)
    return () => observer.disconnect()
  }, [])

  const measure = useCallback((): LifelineLightboxStart | null => {
    const el = cardRef.current
    if (!el) return null
    const rect = el.getBoundingClientRect()
    return {
      cx: rect.left + rect.width / 2,
      cy: rect.top + rect.height / 2,
      w: el.offsetWidth,
      h: el.offsetHeight,
    }
  }, [])

  return (
    <>
      <div
        ref={cardRef}
        data-lifeline-interactive=""
        className={cn(
          "relative mt-3 w-full max-w-[200px] cursor-zoom-in overflow-hidden rounded-xl shadow-lg ring-1 ring-black/10 dark:ring-white/15",
          lightboxStart && "invisible",
          className,
        )}
        onPointerDown={(event) => event.stopPropagation()}
        onClick={(event) => {
          event.stopPropagation()
          if (!lightboxStart) setLightboxStart(measure())
        }}
      >
        <video
          ref={videoRef}
          src={clip.src}
          playsInline
          preload="metadata"
          aria-label={clip.alt}
          className="block aspect-video w-full bg-black object-cover"
        />
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center bg-black/25 text-white">
          <span className="flex h-8 w-8 items-center justify-center rounded-full bg-white/90 text-black shadow">
            <Play className="h-3.5 w-3.5 translate-x-px" fill="currentColor" />
          </span>
        </div>
      </div>
      {lightboxStart && (
        <LifelineLightbox
          clip={clip}
          rotate={0}
          start={lightboxStart}
          getHome={measure}
          onClosed={() => setLightboxStart(null)}
        />
      )}
    </>
  )
}

"use client"

import { useCallback, useRef, useState } from "react"
import { cn } from "@/lib/utils"
import {
  LifelineLightbox,
  type LifelineLightboxStart,
} from "./lifeline-lightbox"
import type { LifelineEventImage } from "./types"

export function LifelineInlineStill({
  image,
  className,
}: {
  image: LifelineEventImage
  className?: string
}) {
  const cardRef = useRef<HTMLDivElement>(null)
  const [lightboxStart, setLightboxStart] =
    useState<LifelineLightboxStart | null>(null)

  const measure = useCallback((): LifelineLightboxStart | null => {
    const el = cardRef.current
    if (!el) return null
    const rect = el.getBoundingClientRect()
    return {
      cx: rect.left + rect.width / 2,
      cy: rect.top + rect.height / 2,
      w: el.offsetWidth,
      h: el.offsetHeight,
    }
  }, [])

  return (
    <>
      <div
        ref={cardRef}
        data-lifeline-interactive=""
        className={cn(
          "relative mt-3 w-full max-w-[200px] cursor-zoom-in overflow-hidden rounded-xl shadow-lg ring-1 ring-black/10 dark:ring-white/15",
          lightboxStart && "invisible",
          className,
        )}
        onPointerDown={(event) => event.stopPropagation()}
        onClick={(event) => {
          event.stopPropagation()
          if (!lightboxStart) setLightboxStart(measure())
        }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={image.src}
          alt={image.alt}
          className="block aspect-video w-full object-cover"
        />
      </div>
      {lightboxStart && (
        <LifelineLightbox
          photo={image}
          rotate={0}
          start={lightboxStart}
          getHome={measure}
          onClosed={() => setLightboxStart(null)}
        />
      )}
    </>
  )
}

