@keyframes lifeline-rail-draw {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes lifeline-marker-in {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes lifeline-labels-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.lifeline-rail-intro {
  transform: scaleX(var(--lifeline-intro-progress, 0));
  transform-origin: left center;
}

.lifeline-rail-intro-vertical {
  transform: scaleY(var(--lifeline-intro-progress, 0));
  transform-origin: top center;
}

.lifeline-marker-intro {
  opacity: 0;
  animation: lifeline-marker-in var(--lifeline-marker-fade-ms, 420ms)
    cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.lifeline-labels-intro {
  opacity: 0;
  animation: lifeline-labels-in var(--lifeline-labels-ms, 600ms)
    cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.lifeline-labels.is-pinned {
  z-index: 20;
}

.lifeline-typeset {
  font-family: var(
    --lifeline-font,
    var(--font-geist-sans),
    ui-sans-serif,
    system-ui,
    sans-serif
  );
}

@media (prefers-reduced-motion: reduce) {
  .lifeline-marker-intro,
  .lifeline-labels-intro {
    animation: none;
    opacity: 1;
  }

  .lifeline-rail-intro,
  .lifeline-rail-intro-vertical {
    transform: none;
  }
}

"use client"

import { ThemeProvider as NextThemesProvider } from "next-themes"
import type { ReactNode } from "react"

export function ThemeProvider({ children }: { children: ReactNode }) {
  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
    >
      {children}
    </NextThemesProvider>
